from pose_join import *
import resource, datetime
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.collections import PolyCollection

def make_figure():
    r1 = json.loads((ROOT / 'raw/R1_RESULTS.json').read_text())
    r4 = json.loads((ROOT / 'raw/R4_RESULTS.json').read_text())
    (fig, ax) = plt.subplots(3, 3, figsize=(12, 10), layout='constrained')
    for (j, (a, b)) in enumerate(zip(r1['rows'], r4['rows'])):
        fam = a['family']
        s = dict(np.load(ROOT / 'exports' / f'{fam}_point_slack.npz', allow_pickle=False))
        sc = ax[j, 0].scatter(s['points'][:, 0], s['points'][:, 2], c=s['slack_mm'], s=1, cmap='coolwarm', vmin=-0.5, vmax=0.8, rasterized=True)
        ax[j, 0].set(title=f'{fam}: fixed intaglio slack', xlabel='local x (mm)', ylabel='local z (mm)', aspect='equal')
        with (ROOT / 'raw' / f'{fam}_R2_POSES.csv').open() as f:
            rows = list(csv.DictReader(f))
        pp = [r for r in rows if float(r['height_mm']) == 14.4 and float(r['tilt_deg']) == 0]
        x = [float(r['top_depth_mm']) for r in pp]
        v = [float(r['retained_volume_mm3']) for r in pp]
        ax[j, 1].plot(x, v, '-', color='#2d5f91', label='YML local rule')
        baseline = json.loads((ROOT / 'raw/R2_RESULTS.json').read_text())['rows'][j]['universal0_5_retained_volume_mm3']
        ax[j, 1].axhline(baseline, color='#ba6c23', ls='--', label='engineering 0.5 mm')
        ax[j, 1].set(title='Free voxel core, upright 18 mm stock', xlabel='top depth in final-equivalent disc (mm)', ylabel='retained virtual volume (mm³)')
        ax[j, 1].legend(fontsize=7)
        g = dict(np.load(ROOT / b['array_path'], allow_pickle=False))
        pts = g['locked_crown_vertices']
        tri = g['vertices'][g['faces']]
        ax[j, 2].scatter(pts[::3, 0], pts[::3, 2], s=0.8, color='#c7c9cc', rasterized=True)
        ax[j, 2].add_collection(PolyCollection(tri[:, :, [0, 2]], facecolors='#3c826a', edgecolors='#225c4a', linewidths=0.1, alpha=0.75, rasterized=True))
        ax[j, 2].autoscale_view()
        ax[j, 2].set(title=f"Closed height core: {b['source_retained_volume_mm3']:.3f} mm³", xlabel='local x (mm)', ylabel='local z (mm)', aspect='equal')
    fig.colorbar(sc, ax=ax[:, 0], label='sampled wall slack (mm)', shrink=0.5)
    fig.suptitle('Local YML wall constraints and locked crown shape\nVirtual preparations; physical qualification UNKNOWN', fontsize=13)
    fig.savefig(ROOT / 'figures/demo.png', dpi=180)
    fig.savefig(ROOT / 'figures/demo.pdf')
    plt.close(fig)

